// NOVEL (hand-authored) — not generated by CLI Printing Press.
// Recorded in .printing-press-patches/garmin-windowed-sync.json.
//
// `garmin-pp-cli history` — the windowed archive walk.
//
// Depth has one control, `--since` (N131 decision D12): `all`, or a date.
// Every series walks oldest to newest and keeps one bookmark, so an
// interrupted run resumes at the day after it (D15).
//
// Why this exists rather than the generated `sync`: Garmin has no "give me
// everything since X" list endpoint. Its daily statistics come from range
// endpoints whose path IS the date range, capped at 28 days per request
// (verified live 2026-09-07 — see the per-series windowDays notes below), and
// its per-day endpoints answer for exactly one date. The press's profiler only
// marks an endpoint syncable when its path has no parameters, and its only
// temporal flag is --dates for a query parameter literally named
// dates/date_range/daterange, so none of these series can be expressed in the
// generated sync at all.
//
// This file owns the whole archive (N131 decision D11, 2026-09-13): the
// calendar walk, the activity feed, the per-activity fan-outs the generated
// sync used to make — detail, splits and heart-rate zones — and the account's
// zone configuration. The generated `sync` is left compiled but unregistered
// and answers with a pointer here; see internal/cli/garmin_sync_stub.go.
//
// pp:data-source live
package cli

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"time"

	"github.com/mvanhorn/printing-press-library/library/health/garmin/internal/store"
	"github.com/spf13/cobra"
)

// garminGetter is the one method the walk needs from the API client. Typing
// against the interface rather than *client.Client is what lets the whole walk
// run against a fake in tests without a network call.
type garminGetter interface {
	Get(ctx context.Context, path string, params map[string]string) (json.RawMessage, error)
}

type garminSeriesKind int

const (
	// seriesWindowed pages history by date range: one request covers
	// windowDays calendar days.
	seriesWindowed garminSeriesKind = iota
	// seriesPerDay answers for exactly one date, so depth costs one request
	// per day. These series are walked over signal days only — the days a
	// cheaper series already shows a reading for — rather than over the
	// calendar.
	seriesPerDay
	// seriesOffsetPaged is the activity feed: offset paging, no date range.
	seriesOffsetPaged
	// seriesPerParent fans out over ids already stored by another series,
	// bounded by the run's floor: a child is fetched only for a parent whose
	// own start day is on or after it (N131 decision D16).
	seriesPerParent
	// seriesSingleDocument is one request answering for the whole account
	// rather than for a date or an id: the response is the document, and
	// the archive keeps exactly one row of it.
	seriesSingleDocument
)

// garminRow is one extracted record: the id it is stored under and the
// calendar day it belongs to.
type garminRow struct {
	id   string
	day  civilDay
	data json.RawMessage
}

// garminSeries describes one archive series end to end.
type garminSeries struct {
	name     string
	kind     garminSeriesKind
	resource string // store resource_type this series writes
	summary  string

	// windowDays is the number of calendar days one request may cover.
	// Each value below was established by a live A/B request on 2026-09-07
	// against a populated account; a series whose larger window returned
	// HTTP 400 is pinned at Garmin's documented 28-day cap.
	windowDays int

	// needsDisplayName marks a path that embeds the account's Garmin
	// display name, which the walk resolves once per run.
	needsDisplayName bool

	// floor is the oldest day this series will ever be asked for. Garmin
	// Connect predates every consumer account in service, so it is where a
	// full fill starts: no discovery call, and no assumption about when the
	// account holder first wore something.
	floor civilDay

	// windowReq builds the request for a date range (seriesWindowed).
	windowReq func(w dayWindow, displayName string) (string, map[string]string)
	// dayReq builds the request for one date (seriesPerDay).
	dayReq func(d civilDay, displayName string) (string, map[string]string)

	// parentResource is the store resource a seriesPerParent series fans
	// out over, parentNoun is how one of its rows is named in a message,
	// childReq builds the request for one parent id, and wrapChild turns
	// the response into the object stored under that id.
	parentResource string
	parentNoun     string
	childReq       func(id string) (string, map[string]string)
	wrapChild      func(id string, raw json.RawMessage) (json.RawMessage, error)

	// docReq builds the one request of a seriesSingleDocument series,
	// docID is the fixed id its single row is stored under, and wrapDoc
	// turns the response into that row.
	docReq  func() (string, map[string]string)
	docID   string
	wrapDoc func(raw json.RawMessage) (json.RawMessage, error)
	// extract turns one response into rows. `requested` is the day or window
	// end that was asked for, used as the day of a payload that carries no
	// calendar field of its own.
	extract func(raw json.RawMessage, requested civilDay) ([]garminRow, error)
}

// garminHistoryFloor is the oldest date the walk will ever request. Garmin
// Connect launched in 2007; nothing older can exist in an account.
var garminHistoryFloor = mustParseCivilDay("2007-01-01")

// garminSeriesCatalog is every series the archive walk knows.
//
// Window sizes, verified live 2026-09-07 against a populated account:
//   - steps / sleep_stats / sleep_score → 28. A 364-day request returns
//     HTTP 400 with an error envelope; a 28-day request returns 200.
//   - resting_hr → 364 proven (a 364-day request returned 364 rows, a
//     28-day request 28).
//   - max_metrics → 364 proven (79 sparse rows across the year).
//   - intensity_minutes → 364 proven (53 weekly rows; this endpoint reports
//     one row per week, so 28 days would cost 13x the requests for the
//     same data).
func garminSeriesCatalog() []garminSeries {
	return []garminSeries{
		{
			name: "steps", kind: seriesWindowed, resource: "steps", windowDays: 28,
			summary: "Daily step count, goal and distance.",
			floor:   garminHistoryFloor,
			windowReq: func(w dayWindow, _ string) (string, map[string]string) {
				return "/usersummary-service/stats/steps/daily/" + w.start.String() + "/" + w.end.String(), nil
			},
			extract: extractDayList("calendarDate"),
		},
		{
			name: "sleep_stats", kind: seriesWindowed, resource: "sleep_stats", windowDays: 28,
			summary: "Per-night sleep summary: stage minutes, sleep score, overnight HRV and resting HR.",
			floor:   garminHistoryFloor,
			windowReq: func(w dayWindow, _ string) (string, map[string]string) {
				return "/sleep-service/stats/sleep/daily/" + w.start.String() + "/" + w.end.String(), nil
			},
			// This endpoint wraps its per-night rows in individualStats and
			// adds an overallStats block scoped to the requested window.
			// Only the per-night rows are archived: overallStats is a
			// derived view of the window we asked for, so storing it would
			// bake this run's arbitrary range into the archive.
			extract: extractNestedDayList([]string{"individualStats"}, "calendarDate"),
		},
		{
			name: "sleep_score", kind: seriesWindowed, resource: "sleep_score", windowDays: 28,
			summary: "Nightly sleep score.",
			floor:   garminHistoryFloor,
			windowReq: func(w dayWindow, _ string) (string, map[string]string) {
				return "/wellness-service/stats/daily/sleep/score/" + w.start.String() + "/" + w.end.String(), nil
			},
			extract: extractDayList("calendarDate"),
		},
		{
			name: "max_metrics", kind: seriesWindowed, resource: "max_metrics", windowDays: 364,
			summary: "VO2 max / MaxMET and fitness age, running and cycling.",
			floor:   garminHistoryFloor,
			windowReq: func(w dayWindow, _ string) (string, map[string]string) {
				return "/metrics-service/metrics/maxmet/daily/" + w.start.String() + "/" + w.end.String(), nil
			},
			extract: extractMaxMetrics,
		},
		{
			name: "intensity_minutes", kind: seriesWindowed, resource: "intensity_minutes", windowDays: 364,
			summary: "Weekly moderate and vigorous intensity minutes against the weekly goal.",
			floor:   garminHistoryFloor,
			windowReq: func(w dayWindow, _ string) (string, map[string]string) {
				return "/usersummary-service/stats/im/weekly/" + w.start.String() + "/" + w.end.String(), nil
			},
			extract: extractDayList("calendarDate"),
		},
		{
			name: "resting_hr", kind: seriesWindowed, resource: "resting_hr", windowDays: 364,
			summary:          "Daily resting heart rate (userstats metric 60).",
			floor:            garminHistoryFloor,
			needsDisplayName: true,
			windowReq: func(w dayWindow, displayName string) (string, map[string]string) {
				return "/userstats-service/wellness/daily/" + displayName, map[string]string{
					"fromDate":  w.start.String(),
					"untilDate": w.end.String(),
					"metricId":  "60",
				}
			},
			extract: extractNestedDayList([]string{"allMetrics", "metricsMap", "WELLNESS_RESTING_HEART_RATE"}, "calendarDate"),
		},
		{
			name: "activities", kind: seriesOffsetPaged, resource: "activities",
			summary: "The activity feed, newest first.",
			floor:   garminHistoryFloor,
		},
		{
			name: "activity_hr_zones", kind: seriesPerParent, resource: "activity_hr_zones",
			summary:        "Seconds in each heart-rate zone, per activity.",
			parentResource: "activities", parentNoun: "activity",
			childReq: func(id string) (string, map[string]string) {
				return "/activity-service/activity/" + id + "/hrTimeInZones", nil
			},
			wrapChild: wrapArrayChild("activityId", "hrTimeInZones", "zoneCount"),
		},
		{
			name: "activity_detail", kind: seriesPerParent, resource: "activity_detail",
			summary:        "The full record of one activity: splits summary, device, weather, laps metadata.",
			parentResource: "activities", parentNoun: "activity",
			childReq: func(id string) (string, map[string]string) {
				return "/activity-service/activity/" + id, nil
			},
			// Stored exactly as Garmin returned it. The generated sync
			// scopes this payload to $.activity for its typed table
			// (internal/cli/sync.go:2231); the archive keeps the whole
			// document instead, because $.activity is a projection for one
			// table's columns and every sibling key it drops — summary
			// totals, device, weather — is the reason to fetch detail at
			// all. The response is already an object carrying its own
			// activityId, so no wrapper is needed to keep the row keyed.
			wrapChild: storeChildAsReturned,
		},
		{
			name: "activity_splits", kind: seriesPerParent, resource: "activity_splits",
			summary:        "Lap and split records for one activity.",
			parentResource: "activities", parentNoun: "activity",
			childReq: func(id string) (string, map[string]string) {
				return "/activity-service/activity/" + id + "/splits", nil
			},
			// Wrapped, and it stays wrapped. Live 2026-09-13 the response is an
			// object carrying activityId, lapDTOs and eventDTOs, so the store would
			// accept it unwrapped — but 1 000 rows are already archived in the
			// wrapped shape, and the wrapper is what keys a row back to its parent
			// without trusting a body field the spec declares only as a
			// FreeFormObject (spec.yaml:1090).
			wrapChild: wrapChildDocument("activityId", "splits"),
		},
		{
			name: "hr_zone_config", kind: seriesSingleDocument, resource: "hr_zone_config",
			summary: "The account's heart-rate zone configuration: the boundaries every per-activity zone row is measured against.",
			docReq: func() (string, map[string]string) {
				return "/biometric-service/heartRateZones", nil
			},
			// One fixed id, no calendar day. This series is the account's
			// current zone settings, not a dated observation: there is one
			// live configuration at a time, so the row is stored under
			// "current" and every re-run upserts that same row in place.
			// Stamping it with a day would turn a setting into a fake time
			// series that grows a row per run and never answers "what are
			// the zones now" without a max() over it.
			docID:   garminHRZoneConfigID,
			wrapDoc: wrapSingleDocument("heartRateZones"),
		},
		{
			name: "daily_summary", kind: seriesPerDay, resource: "daily_summary",
			summary:          "The full daily wellness summary: steps, calories, stress, body battery, respiration, SpO2.",
			needsDisplayName: true,
			floor:            garminHistoryFloor,
			dayReq: func(d civilDay, displayName string) (string, map[string]string) {
				return "/usersummary-service/usersummary/daily/" + displayName, map[string]string{"calendarDate": d.String()}
			},
			extract: extractSingleObject("calendarDate"),
		},
		{
			name: "sleep_detail", kind: seriesPerDay, resource: "sleep_detail",
			summary: "One night in full: sleep stages, overnight HR, HRV, stress, body battery and respiration series.",
			floor:   garminHistoryFloor,
			dayReq: func(d civilDay, _ string) (string, map[string]string) {
				return "/sleep-service/sleep/dailySleepData", map[string]string{"date": d.String()}
			},
			extract: extractSleepDetail,
		},
		{
			name: "daily_hr", kind: seriesPerDay, resource: "daily_hr",
			summary: "All-day heart-rate samples with the day's resting, min and max.",
			floor:   garminHistoryFloor,
			dayReq: func(d civilDay, _ string) (string, map[string]string) {
				return "/wellness-service/wellness/dailyHeartRate/", map[string]string{"date": d.String()}
			},
			extract: extractSingleObject("calendarDate"),
		},
		{
			name: "training_readiness", kind: seriesPerDay, resource: "training_readiness",
			summary: "Training readiness score and its contributing factors.",
			floor:   garminHistoryFloor,
			dayReq: func(d civilDay, _ string) (string, map[string]string) {
				return "/metrics-service/metrics/trainingreadiness/" + d.String(), nil
			},
			extract: extractDayListFallback("calendarDate"),
		},
	}
}

func garminSeriesByName() map[string]garminSeries {
	out := map[string]garminSeries{}
	for _, s := range garminSeriesCatalog() {
		out[s.name] = s
	}
	return out
}

func garminSeriesNames() []string {
	var out []string
	for _, s := range garminSeriesCatalog() {
		out = append(out, s.name)
	}
	sort.Strings(out)
	return out
}

// garminHRZoneConfigID is the single id the heart-rate zone configuration is
// stored under. See the hr_zone_config catalog entry for why it is fixed.
const garminHRZoneConfigID = "current"

// ---------------------------------------------------------------------------
// Child-document wrapping
//
// UpsertKeyedBatch skips any row whose document is not a JSON object
// (internal/store/garmin_series.go:201-205), and a bare array carries no id of
// its own, so a response that is not already a keyed object has to be wrapped
// before it can be archived. Each wrapper below says which of those two
// problems it is solving.
// ---------------------------------------------------------------------------

// perParentShapeError is what a wrapper returns when a response cannot be
// stored as fetched. It carries the reason code and the counts the anomaly
// event records, so the walk reports what the payload actually did rather than
// one generic code for every cause.
type perParentShapeError struct {
	reason   string
	consumed int
	stored   int
}

func (e *perParentShapeError) Error() string { return e.reason }

// wrapArrayChild wraps a bare-array response with the parent id it belongs to
// and the element count. Without the id every parent's payload would collide
// under one storage key; the count is what makes an empty answer visible
// without re-parsing the blob. A response that is not an array is reported
// rather than stored under a guess.
func wrapArrayChild(idKey, arrayKey, countKey string) func(string, json.RawMessage) (json.RawMessage, error) {
	return func(id string, raw json.RawMessage) (json.RawMessage, error) {
		var items []json.RawMessage
		if err := json.Unmarshal(raw, &items); err != nil {
			return nil, &perParentShapeError{reason: "per_parent_shape_unrecognized"}
		}
		wrapped, err := json.Marshal(map[string]any{
			idKey:             id,
			arrayKey:          json.RawMessage(raw),
			countKey:          len(items),
			"garminWrappedBy": "history",
		})
		if err != nil {
			return nil, &perParentShapeError{reason: "per_parent_wrap_failed", consumed: 1}
		}
		return wrapped, nil
	}
}

// wrapChildDocument wraps whatever the endpoint returned under one key beside
// the parent id, without asserting the payload's shape. It is for a child
// endpoint whose live shape this tool has not yet seen: array or object, the
// stored row is one object keyed by its parent.
func wrapChildDocument(idKey, bodyKey string) func(string, json.RawMessage) (json.RawMessage, error) {
	return func(id string, raw json.RawMessage) (json.RawMessage, error) {
		wrapped, err := json.Marshal(map[string]any{
			idKey:             id,
			bodyKey:           raw,
			"garminWrappedBy": "history",
		})
		if err != nil {
			return nil, &perParentShapeError{reason: "per_parent_wrap_failed", consumed: 1}
		}
		return wrapped, nil
	}
}

// storeChildAsReturned keeps an object response byte-for-byte. The guard is
// the store's own rule, so a payload that reaches storeRows here is one
// UpsertKeyedBatch will accept rather than silently skip.
func storeChildAsReturned(_ string, raw json.RawMessage) (json.RawMessage, error) {
	if _, err := store.DecodeJSONObject(raw); err != nil {
		return nil, &perParentShapeError{reason: "per_parent_shape_unrecognized"}
	}
	return raw, nil
}

// wrapSingleDocument wraps a whole-account response under one key so it is an
// object regardless of what the endpoint returned.
func wrapSingleDocument(bodyKey string) func(json.RawMessage) (json.RawMessage, error) {
	return func(raw json.RawMessage) (json.RawMessage, error) {
		wrapped, err := json.Marshal(map[string]any{
			bodyKey:           raw,
			"garminWrappedBy": "history",
		})
		if err != nil {
			return nil, &perParentShapeError{reason: "document_wrap_failed", consumed: 1}
		}
		return wrapped, nil
	}
}

// ---------------------------------------------------------------------------
// Response extraction
// ---------------------------------------------------------------------------

func jsonChild(raw json.RawMessage, key string) (json.RawMessage, bool) {
	var obj map[string]json.RawMessage
	if err := json.Unmarshal(raw, &obj); err != nil {
		return nil, false
	}
	child, ok := obj[key]
	if !ok || len(child) == 0 || string(child) == "null" {
		return nil, false
	}
	return child, true
}

func jsonAtPath(raw json.RawMessage, path []string) (json.RawMessage, bool) {
	current := raw
	for _, key := range path {
		child, ok := jsonChild(current, key)
		if !ok {
			return nil, false
		}
		current = child
	}
	return current, true
}

func jsonStringField(raw json.RawMessage, key string) string {
	child, ok := jsonChild(raw, key)
	if !ok {
		return ""
	}
	var s string
	if err := json.Unmarshal(child, &s); err != nil {
		return ""
	}
	return s
}

// dayFromValue accepts both "2026-09-07" and "2026-09-07 06:11:00", which is
// how Garmin spells a calendar date and a local timestamp respectively.
func dayFromValue(v string) (civilDay, bool) {
	if len(v) < 10 {
		return civilDay{}, false
	}
	d, err := parseCivilDay(v[:10])
	if err != nil {
		return civilDay{}, false
	}
	return d, true
}

// rowsFromList turns a JSON array into day-keyed rows. An item with no usable
// calendar field is dropped rather than stored under a guessed key; the caller
// sees the shortfall as a stored-vs-consumed gap and reports it.
func rowsFromList(list json.RawMessage, dayField string, fallback civilDay) ([]garminRow, error) {
	var items []json.RawMessage
	if err := json.Unmarshal(list, &items); err != nil {
		return nil, fmt.Errorf("expected a JSON array: %w", err)
	}
	rows := make([]garminRow, 0, len(items))
	for _, item := range items {
		day, ok := dayFromValue(jsonStringField(item, dayField))
		if !ok {
			if fallback.isZero() {
				continue
			}
			day = fallback
		}
		rows = append(rows, garminRow{id: day.String(), day: day, data: item})
	}
	return rows, nil
}

func extractDayList(dayField string) func(json.RawMessage, civilDay) ([]garminRow, error) {
	return func(raw json.RawMessage, _ civilDay) ([]garminRow, error) {
		return rowsFromList(raw, dayField, civilDay{})
	}
}

// extractDayListFallback keys a row by the requested day when the payload
// carries no calendar field. Garmin's training-readiness response is a list
// whose shape varies with the device that produced it.
func extractDayListFallback(dayField string) func(json.RawMessage, civilDay) ([]garminRow, error) {
	return func(raw json.RawMessage, requested civilDay) ([]garminRow, error) {
		return rowsFromList(raw, dayField, requested)
	}
}

func extractNestedDayList(path []string, dayField string) func(json.RawMessage, civilDay) ([]garminRow, error) {
	return func(raw json.RawMessage, _ civilDay) ([]garminRow, error) {
		list, ok := jsonAtPath(raw, path)
		if !ok {
			// An absent branch is an empty window, not a malformed
			// response: Garmin omits the container for a range with no
			// readings.
			return nil, nil
		}
		return rowsFromList(list, dayField, civilDay{})
	}
}

func extractSingleObject(dayField string) func(json.RawMessage, civilDay) ([]garminRow, error) {
	return func(raw json.RawMessage, requested civilDay) ([]garminRow, error) {
		var obj map[string]json.RawMessage
		if err := json.Unmarshal(raw, &obj); err != nil {
			return nil, fmt.Errorf("expected a JSON object: %w", err)
		}
		if len(obj) == 0 {
			return nil, nil
		}
		day, ok := dayFromValue(jsonStringField(raw, dayField))
		if !ok {
			day = requested
		}
		if day.isZero() {
			return nil, nil
		}
		return []garminRow{{id: day.String(), day: day, data: raw}}, nil
	}
}

// extractSleepDetail keys a night by dailySleepDTO.calendarDate. A response
// whose dailySleepDTO is absent or null is a night with no recorded sleep —
// an empty result, not a failure.
func extractSleepDetail(raw json.RawMessage, requested civilDay) ([]garminRow, error) {
	dto, ok := jsonChild(raw, "dailySleepDTO")
	if !ok {
		return nil, nil
	}
	day, ok := dayFromValue(jsonStringField(dto, "calendarDate"))
	if !ok {
		day = requested
	}
	if day.isZero() {
		return nil, nil
	}
	return []garminRow{{id: day.String(), day: day, data: raw}}, nil
}

// extractMaxMetrics reads the calendar date out of whichever sport block the
// response carries. Garmin returns one entry per measured day with a `generic`
// (running) block, a `cycling` block, or both; days with no measurement are
// simply absent, which is why this series is sparse rather than daily.
func extractMaxMetrics(raw json.RawMessage, _ civilDay) ([]garminRow, error) {
	var items []json.RawMessage
	if err := json.Unmarshal(raw, &items); err != nil {
		return nil, fmt.Errorf("expected a JSON array: %w", err)
	}
	rows := make([]garminRow, 0, len(items))
	for _, item := range items {
		var day civilDay
		for _, block := range []string{"generic", "cycling"} {
			child, ok := jsonChild(item, block)
			if !ok {
				continue
			}
			if d, parsed := dayFromValue(jsonStringField(child, "calendarDate")); parsed {
				day = d
				break
			}
		}
		if day.isZero() {
			continue
		}
		rows = append(rows, garminRow{id: day.String(), day: day, data: item})
	}
	return rows, nil
}

// ---------------------------------------------------------------------------
// Event emitter
// ---------------------------------------------------------------------------

// garminEmitter writes the same event vocabulary the generated sync uses —
// sync_start, sync_progress, sync_warning, sync_anomaly, sync_summary — so one
// consumer can read both. It never returns an error and never panics: a
// telemetry failure must not break the walk it observes, so every write is
// best-effort and every dynamic string goes through json.Marshal rather than
// being interpolated into a hand-built object.
type garminEmitter struct {
	w       io.Writer
	machine bool
	// noteW carries the lines that are neither an event nor an error: the
	// cost estimate and the one-off notices. In human mode they go to
	// stderr so the run's own output stays pipeable; in machine mode the
	// estimate becomes an event and the notices are dropped, because a
	// machine reader has the same facts in the event stream.
	noteW io.Writer
}

func (e *garminEmitter) raw(line string) {
	if e == nil || e.w == nil {
		return
	}
	_, _ = io.WriteString(e.w, line+"\n")
}

func jsonString(s string) string {
	b, err := json.Marshal(s)
	if err != nil {
		return `""`
	}
	return string(b)
}

func (e *garminEmitter) human(format string, args ...any) {
	if e == nil || e.w == nil || e.machine {
		return
	}
	_, _ = fmt.Fprintf(e.w, format+"\n", args...)
}

func (e *garminEmitter) start(series string) {
	if e == nil {
		return
	}
	if e.machine {
		e.raw(`{"event":"sync_start","resource":` + jsonString(series) + `}`)
		return
	}
	e.human("  %s ...", series)
}

// progress reports one unit of work — a window, a day, a page — and the
// bookmark as it now stands. The bookmark is the interesting half: it is where
// a killed run will resume, so printing it is what makes "interrupting is
// safe" something the caller can see rather than something the docs claim.
func (e *garminEmitter) progress(series string, fetched int, window, bookmark string) {
	if e == nil {
		return
	}
	if e.machine {
		e.raw(`{"event":"sync_progress","resource":` + jsonString(series) +
			`,"fetched":` + strconv.Itoa(fetched) + `,"window":` + jsonString(window) +
			`,"bookmark":` + jsonString(bookmark) + `}`)
		return
	}
	if bookmark == "" {
		e.human("    %s %s: %d rows", series, window, fetched)
		return
	}
	e.human("    %s %s: %d rows (complete through %s)", series, window, fetched, bookmark)
}

// note is a human-mode line that is not an event: it goes to noteW, so it
// never lands in the middle of piped output, and it is silent in machine mode.
func (e *garminEmitter) note(message string) {
	if e == nil || e.machine || e.noteW == nil {
		return
	}
	_, _ = fmt.Fprintln(e.noteW, message)
}

// estimate reports what the expensive half of the run will cost, before it
// starts. sync_estimate is the one event name here that the generated sync
// vocabulary does not have: there is no generated event for "this is what the
// next few thousand requests will cost you", and inventing a field on
// sync_progress would have made a cost projection look like work done.
func (e *garminEmitter) estimate(est garminWorkEstimate) {
	if e == nil {
		return
	}
	if e.machine {
		e.raw(fmt.Sprintf(`{"event":"sync_estimate","since":%s,"requests":%d,"minutes":%.1f,"megabytes":%.1f}`,
			jsonString(est.Since), est.Requests, est.Minutes, est.Megabytes))
		return
	}
	e.note(est.line())
}

func (e *garminEmitter) warn(series, reason, message string) {
	if e == nil {
		return
	}
	if e.machine {
		e.raw(`{"event":"sync_warning","resource":` + jsonString(series) +
			`,"reason":` + jsonString(reason) + `,"message":` + jsonString(message) + `}`)
		return
	}
	e.human("  warning: %s: %s", series, message)
}

func (e *garminEmitter) anomaly(series, reason string, consumed, stored int) {
	if e == nil {
		return
	}
	if e.machine {
		e.raw(`{"event":"sync_anomaly","resource":` + jsonString(series) +
			`,"consumed":` + strconv.Itoa(consumed) +
			`,"stored":` + strconv.Itoa(stored) +
			`,"reason":` + jsonString(reason) + `}`)
		return
	}
	e.human("  anomaly: %s: %s (consumed %d, stored %d)", series, reason, consumed, stored)
}

func (e *garminEmitter) summary(totalRecords, resources, success, warned, errored int, d time.Duration) {
	if e == nil {
		return
	}
	if e.machine {
		e.raw(fmt.Sprintf(`{"event":"sync_summary","total_records":%d,"resources":%d,"success":%d,"warned":%d,"errored":%d,"duration_ms":%d}`,
			totalRecords, resources, success, warned, errored, d.Milliseconds()))
		return
	}
	e.human("\n%d rows across %d series in %s (%d ok, %d warned, %d errored)",
		totalRecords, resources, d.Round(time.Millisecond), success, warned, errored)
}

// ---------------------------------------------------------------------------
// Rate limiting and pacing
// ---------------------------------------------------------------------------

// errGarminRateLimited aborts the whole walk. Garmin's edge rate-limits by
// client shape, and our own research recorded 429s arriving in bursts, so the
// honest response to the first one is to stop asking — not to keep walking the
// remaining series and convert one 429 into a hundred.
var errGarminRateLimited = errors.New("garmin rate-limited the request; the walk stopped rather than retrying")

// errGarminWallOfFailures stops a run whose every request is failing.
//
// Observed live on 2026-09-07: a run whose credential had gone stale answered
// HTTP 403 to all 39 of its requests and emitted 39 separate warnings for one
// condition, then kept going. Neither 403 nor 401 carries a Retry-After or a
// rate-limit error type, so nothing in the per-call error path distinguishes
// "this request was refused" from "this client is finished". A whole run
// failing is a different fact from a request failing, and it deserves to be
// reported once and acted on immediately rather than restated per call.
var errGarminWallOfFailures = errors.New("every recent request failed; the walk stopped rather than continuing to ask")

// errGarminWindowDenied marks a window Garmin refused as pre-history.
//
// Garmin answers HTTP 403 to a date range that reaches past the start of the
// account's own history — the same status it gives a credential that has gone
// stale, with nothing in the response to tell the two apart. Two facts about
// the walk tell them apart, and both must hold before a 403 is read as the
// account's history start rather than as a fault: the series has not stored a
// row yet (so the window is below everything this account has ever shown us),
// and this run has already had one request answered with HTTP 200 (so the
// credential demonstrably works). Otherwise the refusal counts toward the
// consecutive-failure wall and the series ends with its bookmark unmoved, to
// be retried on the next run.
//
// Live on 2026-09-12: the old backward walk exited 5 because the first window
// of intensity_minutes answered 403 and ten refusals in a row across the
// ranged series read as a dead credential, so the run stopped before
// activities and every per-day series was attempted.
var errGarminWindowDenied = errors.New("garmin refused this window")

// defaultMaxConsecutiveFailures is how many failures in a row end a run. It is
// well above the handful a flaky connection produces and well below the
// hundreds a walk would otherwise spend proving the door is shut.
const defaultMaxConsecutiveFailures = 10

func isRateLimited(err error) bool {
	if err == nil {
		return false
	}
	return strings.Contains(err.Error(), "HTTP 429") || strings.Contains(err.Error(), "rate limited")
}

// isForbidden matches on the message the way isRateLimited does. The client
// rewraps an error whenever it masks credential text (internal/client
// maskedError), which drops the *client.APIError the status code lives on, so
// the status is only reliably readable as the text the error prints.
func isForbidden(err error) bool {
	if err == nil {
		return false
	}
	return strings.Contains(err.Error(), "HTTP 403")
}

// isWalkAborted reports the two conditions that end a whole run rather than
// one series: a rate limit, and a wall of consecutive failures.
func isWalkAborted(err error) bool {
	return errors.Is(err, errGarminRateLimited) || errors.Is(err, errGarminWallOfFailures)
}

// garminPacer spaces requests. The default 300 ms is the interval a live
// 94-window live fill walked at without a single 429 (N131 §9.2).
type garminPacer struct {
	delay time.Duration
	sleep func(time.Duration)
	first bool
}

func newGarminPacer(delay time.Duration, sleep func(time.Duration)) *garminPacer {
	if sleep == nil {
		sleep = time.Sleep
	}
	return &garminPacer{delay: delay, sleep: sleep, first: true}
}

func (p *garminPacer) wait() {
	if p == nil {
		return
	}
	if p.first {
		p.first = false
		return
	}
	if p.delay > 0 {
		p.sleep(p.delay)
	}
}

// ---------------------------------------------------------------------------
// The walk
// ---------------------------------------------------------------------------

// garminDepthMode is which of --since's three states a run is in. They are
// three, not two, because "the caller said nothing" and "the caller said all"
// mean different things on a series that is already filled: a plain `history`
// keeps the depth the archive already has, while an explicit --since all asks
// for everything (D15).
type garminDepthMode int

const (
	// depthStored is --since absent: keep whatever depth each series
	// already has, and fill forward from its bookmark.
	depthStored garminDepthMode = iota
	// depthAll is --since all: fill from each series' own floor.
	depthAll
	// depthFrom is --since YYYY-MM-DD: fill from that day, or from the
	// series' floor if that is later.
	depthFrom
)

// garminDepth is the parsed --since value.
type garminDepth struct {
	mode garminDepthMode
	day  civilDay
}

func (d garminDepth) String() string {
	switch d.mode {
	case depthAll:
		return "all"
	case depthFrom:
		return d.day.String()
	}
	return ""
}

// garminRefreshDays is how many of the newest complete signal days a per-day
// series re-requests on every run. A day can be fetched before the watch that
// recorded it has finished syncing — the owner's bike computer uploads when he
// gets home — so the newest days are asked for again rather than frozen at
// whatever was there when they first came into range.
const garminRefreshDays = 7

type garminWalkOptions struct {
	series           []string
	depth            garminDepth
	delay            time.Duration
	maxPages         int
	maxDependents    int
	activityPageSize int
	// maxConsecutiveFailures ends the run when this many calls fail in a
	// row. Zero means the default.
	maxConsecutiveFailures int
	strict                 bool
	now                    func() time.Time
	loc                    *time.Location
	sleep                  func(time.Duration)
}

type garminSeriesOutcome struct {
	series  string
	stored  int
	calls   int
	warned  bool
	errored bool
	err     error
	// boundedEmpty says this run's floor left the series nothing to ask for.
	// An empty table is then what the caller asked for rather than a zero
	// nobody has proven, so the never-stored-a-row warning stays quiet.
	boundedEmpty bool
}

type garminWalker struct {
	client      garminGetter
	db          *store.Store
	emit        *garminEmitter
	opts        garminWalkOptions
	planner     *garminPlanner
	pacer       *garminPacer
	displayName string
	nameLoaded  bool
	calls       int
	// consecutiveFailures counts failed calls since the last success,
	// across every series in the run.
	consecutiveFailures int
	// sawHTTP200 records that Garmin has answered at least one request in
	// this run. It is the half of the pre-history test that speaks for the
	// credential: until it is true, a 403 is as likely to be a dead token as
	// a date before the account existed.
	sawHTTP200 bool
	// noticedShallowSince keeps the "--since is above what the archive
	// already holds" line to one per run rather than one per series.
	noticedShallowSince bool
}

// get is the single choke point for every API call: it paces, counts, and
// converts a 429 into the sentinel that stops the run.
func (w *garminWalker) get(ctx context.Context, path string, params map[string]string) (json.RawMessage, error) {
	return w.getClassified(ctx, path, params, false)
}

// getHistoryEdge is get for a window that may lie before the account existed,
// the one place a refused window is data rather than a fault. The caller
// decides that per request; see errGarminWindowDenied for the two conditions.
func (w *garminWalker) getHistoryEdge(ctx context.Context, path string, params map[string]string, atEdge bool) (json.RawMessage, error) {
	return w.getClassified(ctx, path, params, atEdge)
}

func (w *garminWalker) getClassified(ctx context.Context, path string, params map[string]string, atHistoryEdge bool) (json.RawMessage, error) {
	w.pacer.wait()
	w.calls++
	data, err := w.client.Get(ctx, path, params)
	if isRateLimited(err) {
		w.consecutiveFailures++
		return nil, fmt.Errorf("%w: %v", errGarminRateLimited, err)
	}
	if err != nil {
		if atHistoryEdge && isForbidden(err) {
			// Neither counted nor cleared. Not counted, because a refusal
			// past the history start is not a failing client; not cleared,
			// because it is not a working one either, so a credential that
			// dies mid-run still hits the wall on the next request it makes
			// rather than walking every remaining window first.
			return nil, fmt.Errorf("%w: %v", errGarminWindowDenied, err)
		}
		w.consecutiveFailures++
		limit := w.opts.maxConsecutiveFailures
		if limit < 1 {
			limit = defaultMaxConsecutiveFailures
		}
		if w.consecutiveFailures >= limit {
			return nil, fmt.Errorf("%w (%d in a row, most recently: %v)", errGarminWallOfFailures, w.consecutiveFailures, err)
		}
		return nil, err
	}
	w.consecutiveFailures = 0
	w.sawHTTP200 = true
	return data, err
}

// resolveDisplayName fetches the account's Garmin display name once per run.
// Three series embed it in their path; without it they cannot be requested.
func (w *garminWalker) resolveDisplayName(ctx context.Context) (string, error) {
	if w.nameLoaded {
		return w.displayName, nil
	}
	data, err := w.get(ctx, "/userprofile-service/socialProfile", nil)
	if err != nil {
		return "", err
	}
	name := jsonStringField(data, "displayName")
	if name == "" {
		return "", errors.New("social profile carried no displayName")
	}
	w.displayName = name
	w.nameLoaded = true
	return name, nil
}

// storeRows writes one window's rows and returns how many landed.
func (w *garminWalker) storeRows(series garminSeries, rows []garminRow) (int, error) {
	if len(rows) == 0 {
		return 0, nil
	}
	keyed := make([]store.KeyedRow, 0, len(rows))
	for _, r := range rows {
		keyed = append(keyed, store.KeyedRow{ID: r.id, Data: r.data})
	}
	stored, skipped, err := w.db.UpsertKeyedBatch(series.resource, keyed)
	if err != nil {
		return stored, err
	}
	if skipped > 0 {
		w.emit.anomaly(series.name, "rows_without_usable_key", len(rows), stored)
	}
	return stored, nil
}

// mirrorSyncState copies a series' progress into the generated sync_state
// table so doctor, tail and anything else reading generated state sees the
// windowed series too. The authoritative bookmark stays in
// garmin_series_state; this is a projection, and a failure to write it is a
// warning rather than a lost window.
//
// The projection is written once, when a series finishes. A run killed
// mid-series therefore leaves doctor's sync_state behind the real bookmark
// until the next run completes that series — garmin_series_state is
// checkpointed after every window and is the one to read, which is what
// `history --status` does.
func (w *garminWalker) mirrorSyncState(series string, st store.GarminSeriesState) {
	if err := w.db.SaveSyncState(series, st.LastCompleteDay, st.TotalRows); err != nil {
		w.emit.warn(series, "sync_state_mirror_failed", "windowed state was saved but the generated sync_state row was not updated: "+err.Error())
	}
}

func dayRange(rows []garminRow) (oldest, newest civilDay) {
	for _, r := range rows {
		oldest = minDay(oldest, r.day)
		newest = maxDay(newest, r.day)
	}
	return oldest, newest
}

// garminWindowStatus is what one window request produced.
type garminWindowStatus int

const (
	// windowStored: HTTP 200, rows extracted and written (possibly none).
	windowStored garminWindowStatus = iota
	// windowDenied: HTTP 403 on a window that lies before this account's
	// history, which the walk steps over. See errGarminWindowDenied.
	windowDenied
	// windowFailed: anything else. The bookmark stops moving.
	windowFailed
)

// fetchWindow makes one windowed request and stores what it returned. A
// non-nil error is fatal to the run — a rate limit, a wall of failures, or a
// store that would not write; everything else is reported as a status.
func (w *garminWalker) fetchWindow(ctx context.Context, s garminSeries, win dayWindow, displayName string, atEdge bool, out *garminSeriesOutcome) (garminWindowStatus, int, error) {
	path, params := s.windowReq(win, displayName)
	data, callErr := w.getHistoryEdge(ctx, path, params, atEdge)
	if callErr != nil {
		if isWalkAborted(callErr) {
			return windowFailed, 0, callErr
		}
		if errors.Is(callErr, errGarminWindowDenied) {
			return windowDenied, 0, nil
		}
		out.warned = true
		w.emit.warn(s.name, "window_fetch_failed", "window "+win.String()+": "+callErr.Error())
		return windowFailed, 0, nil
	}
	rows, exErr := s.extract(data, win.end)
	if exErr != nil {
		out.warned = true
		w.emit.anomaly(s.name, "window_shape_unrecognized", 0, 0)
		return windowFailed, 0, nil
	}
	stored, storeErr := w.storeRows(s, rows)
	if storeErr != nil {
		return windowFailed, 0, storeErr
	}
	out.stored += stored
	return windowStored, stored, nil
}

// atHistoryEdge says whether a 403 on the next request would be Garmin
// declining a date range from before this account existed rather than
// declining this client. Both halves have to hold: the series has never stored
// a row (so nothing proves the account reaches that far back), and Garmin has
// already answered something in this run with a 200 (so the credential works).
func (w *garminWalker) atHistoryEdge(rowsAtStart, storedThisRun int) bool {
	return rowsAtStart == 0 && storedThisRun == 0 && w.sawHTTP200
}

// noticeShallowSince says once per run that --since asked for less depth than
// the archive already has. It is a notice rather than a warning because
// nothing is wrong: the deeper rows stay, and the run simply does not go back
// down to fetch what it already holds.
func (w *garminWalker) noticeShallowSince(st store.GarminSeriesState) {
	if w.opts.depth.mode != depthFrom || w.noticedShallowSince {
		return
	}
	earliest := mustDay(st.EarliestDay)
	if earliest.isZero() || !earliest.before(w.opts.depth.day) {
		return
	}
	w.noticedShallowSince = true
	w.emit.note(fmt.Sprintf(
		"The archive already reaches back to %s, deeper than --since %s; nothing below that date is fetched again and nothing already stored is dropped.",
		earliest, w.opts.depth.day))
}

// finishSeries recounts the series' rows from the archive and saves the state.
//
// Recounted, not accumulated: this walk re-requests the feed's boundary day
// and a refresh window of days on every run, and an interrupted extension leg
// restarts from the floor, so a running total would count the same row once
// per run — the mistake walkSingleDocument already documents for its own case.
func (w *garminWalker) finishSeries(s garminSeries, st store.GarminSeriesState, out *garminSeriesOutcome) {
	rows, err := w.db.CountResourceRows(s.resource)
	if err == nil {
		st.TotalRows = rows
	}
	if saveErr := w.db.SaveGarminSeriesState(st); saveErr != nil {
		out.errored, out.err = true, saveErr
		return
	}
	w.mirrorSyncState(s.name, st)
}

// walkWindowed runs one date-range series oldest day first.
//
// Two legs, one bookmark. The extension leg runs only when this run asks for a
// floor below the range already filled: it walks from that floor up to the day
// before the filled range and stamps the new floor only when it completes, so
// an interrupted extension simply starts again from the floor next run rather
// than leaving a gap nothing would ever return to. The forward leg then walks
// from the day after the bookmark to today, checkpointing after every window,
// which is what makes a killed run resume at bookmark + 1.
func (w *garminWalker) walkWindowed(ctx context.Context, s garminSeries) garminSeriesOutcome {
	out := garminSeriesOutcome{series: s.name}
	st, err := w.db.GetGarminSeriesState(s.name)
	if err != nil {
		out.errored, out.err = true, err
		return out
	}
	st = garminResumableState(st)

	displayName := ""
	if s.needsDisplayName {
		displayName, err = w.resolveDisplayName(ctx)
		if err != nil {
			out.errored, out.err = true, err
			return out
		}
	}
	rowsAtStart, err := w.db.CountResourceRows(s.resource)
	if err != nil {
		out.errored, out.err = true, err
		return out
	}

	now := today(w.opts.now, w.opts.loc)
	ceiling := completeDayCeiling(now)
	filled := garminSeriesFilled(st)
	floor := w.planner.windowedFloor(s, st)
	w.noticeShallowSince(st)

	denied := 0
	lastDenied := civilDay{}
	okWindows := 0

	// --- extension leg: only when this run reaches below the filled range.
	if filled {
		earliest := mustDay(st.EarliestDay)
		if floor.before(earliest) {
			broken := false
			for _, win := range planForwardWindows(floor, earliest.addDays(-1), s.windowDays) {
				status, stored, fatal := w.fetchWindow(ctx, s, win, displayName,
					w.atHistoryEdge(rowsAtStart, out.stored), &out)
				if fatal != nil {
					out.errored, out.err = true, fatal
					return out
				}
				switch status {
				case windowDenied:
					denied++
					lastDenied = win.end
				case windowFailed:
					broken = true
				case windowStored:
					okWindows++
					w.emit.progress(s.name, stored, win.String(), st.LastCompleteDay)
				}
				if broken {
					break
				}
			}
			// A leg whose every window Garmin refused proves nothing about
			// the range it asked for, so the floor does not move over it:
			// the same range is asked for again next run, which is what the
			// all_windows_refused warning tells the caller happens.
			if !broken && okWindows > 0 {
				st.EarliestDay = minDay(earliest, floor).String()
			}
			if saveErr := w.db.SaveGarminSeriesState(st); saveErr != nil {
				out.errored, out.err = true, saveErr
				return out
			}
		}
	}

	// --- forward leg: from the day after the bookmark to today.
	from := floor
	if filled {
		from = mustDay(st.LastCompleteDay).addDays(1)
	}
	if from.after(now) {
		// Already complete through yesterday; still refresh today, whose
		// row is partial by definition.
		from = now
	}
	forwardBroken := false
	for _, win := range planForwardWindows(from, now, s.windowDays) {
		status, stored, fatal := w.fetchWindow(ctx, s, win, displayName,
			w.atHistoryEdge(rowsAtStart, out.stored), &out)
		if fatal != nil {
			out.errored, out.err = true, fatal
			return out
		}
		switch status {
		case windowDenied:
			denied++
			lastDenied = win.end
			continue
		case windowFailed:
			// Later windows still fetch — their rows are real — but the
			// bookmark stops here, so the next run re-requests the gap
			// instead of stepping over it forever.
			forwardBroken = true
			continue
		}
		okWindows++
		if !forwardBroken {
			st.LastCompleteDay = maxDay(mustDay(st.LastCompleteDay), minDay(win.end, ceiling)).String()
			// A floor above the newest complete day describes no range at
			// all; stamping it would leave earliest_day after
			// last_complete_day and pin the depth there.
			if !from.after(ceiling) {
				st.EarliestDay = minDay(mustDay(st.EarliestDay), from).String()
			}
		}
		w.emit.progress(s.name, stored, win.String(), st.LastCompleteDay)
		if saveErr := w.db.SaveGarminSeriesState(st); saveErr != nil {
			out.errored, out.err = true, saveErr
			return out
		}
	}

	switch {
	case denied > 0 && okWindows == 0:
		// A dead or blocked token refuses everything, and so does a date
		// range before the account existed. A series that got nothing but
		// refusals has not proven which, so it is not marked complete.
		st.StopReason = "all_windows_refused"
		out.warned = true
		w.emit.warn(s.name, "all_windows_refused", fmt.Sprintf(
			"Garmin refused all %d window(s) this run asked for (HTTP 403), the most recent ending %s; nothing was marked complete, so the same range is asked for again next run.",
			denied, lastDenied))
	case forwardBroken:
		st.StopReason = "interrupted"
	default:
		st.StopReason = ""
	}
	if denied > 0 && okWindows > 0 {
		out.warned = true
		w.emit.warn(s.name, "window_denied", fmt.Sprintf(
			"Garmin refused %d window(s) (HTTP 403), the most recent ending %s; those ranges reach past this account's history start and were treated as empty.",
			denied, lastDenied))
	}

	w.finishSeries(s, st, &out)
	return out
}

// garminResumableState drops the filled range a retired backward walk wrote.
// That walk's earliest_day meant "the oldest day a row exists for", not "the
// oldest day this walk requested", so carrying it into a walk_version-2 row
// would certify coverage nothing has proven. The stored rows stay; only the
// claim about them goes.
func garminResumableState(st store.GarminSeriesState) store.GarminSeriesState {
	if st.WalkVersion < store.GarminWalkVersion {
		st.EarliestDay, st.LastCompleteDay, st.StopReason = "", "", ""
	}
	return st
}

// mustDay parses a stored day string, returning the zero day for "" or junk.
// Stored state is our own writing, so a parse failure means a hand-edited
// database, not an API surprise: treat it as unset rather than fail the run.
func mustDay(s string) civilDay {
	if s == "" {
		return civilDay{}
	}
	d, err := parseCivilDay(s)
	if err != nil {
		return civilDay{}
	}
	return d
}

// walkPerDay runs one per-date series over signal days, oldest first.
//
// One request buys one day here, and the payloads are large — a single night
// of sleep_detail measured 88 KB on the reference archive — so the walk asks
// only for days something was actually recorded: a day with a row in one of
// the cheap series, or a day an activity started on (garminSignalResources).
// On the reference accounts that is every calendar day for a daily wearer and
// about 134 days out of 1 908 for an occasional cyclist, which is the whole
// difference between a fill that is worth running and one that is not.
//
// A day that was requested and came back empty sits inside the filled range
// and is never requested again; the newest garminRefreshDays signal days are
// the exception, re-requested every run because a day can be fetched before
// the device that recorded it has finished uploading.
func (w *garminWalker) walkPerDay(ctx context.Context, s garminSeries) garminSeriesOutcome {
	out := garminSeriesOutcome{series: s.name}
	st, err := w.db.GetGarminSeriesState(s.name)
	if err != nil {
		out.errored, out.err = true, err
		return out
	}
	st = garminResumableState(st)
	work, err := w.planner.perDayWork(s, st)
	if err != nil {
		out.errored, out.err = true, err
		return out
	}
	w.noticeShallowSince(st)

	displayName := ""
	if s.needsDisplayName && len(work.days) > 0 {
		displayName, err = w.resolveDisplayName(ctx)
		if err != nil {
			out.errored, out.err = true, err
			return out
		}
	}

	ceiling := completeDayCeiling(today(w.opts.now, w.opts.loc))
	filled := garminSeriesFilled(st)
	earliest := mustDay(st.EarliestDay)
	extBroken, forwardBroken := false, false

	for _, day := range work.days {
		extension := filled && day.before(earliest)
		path, params := s.dayReq(day, displayName)
		data, callErr := w.get(ctx, path, params)
		if callErr != nil {
			if isWalkAborted(callErr) {
				out.errored, out.err = true, callErr
				return out
			}
			out.warned = true
			w.emit.warn(s.name, "day_fetch_failed", day.String()+": "+callErr.Error())
			if extension {
				extBroken = true
			} else {
				forwardBroken = true
			}
			continue
		}
		rows, exErr := s.extract(data, day)
		if exErr != nil {
			out.warned = true
			w.emit.anomaly(s.name, "day_shape_unrecognized", 0, 0)
			if extension {
				extBroken = true
			} else {
				forwardBroken = true
			}
			continue
		}
		stored, storeErr := w.storeRows(s, rows)
		if storeErr != nil {
			out.errored, out.err = true, storeErr
			return out
		}
		out.stored += stored
		// The bookmark advances over a requested day whether or not it
		// carried data: a day asked for and answered empty is filled, and
		// re-asking it every run would cost one request per empty day
		// forever.
		if !extension && !forwardBroken {
			st.LastCompleteDay = maxDay(mustDay(st.LastCompleteDay), minDay(day, ceiling)).String()
			if saveErr := w.db.SaveGarminSeriesState(st); saveErr != nil {
				out.errored, out.err = true, saveErr
				return out
			}
		}
		w.emit.progress(s.name, stored, day.String(), st.LastCompleteDay)
	}

	// The same rule as the windowed walk: a floor above the newest complete
	// day is not a range, so nothing is stamped from it.
	if !work.coverFrom.isZero() && !work.coverFrom.after(ceiling) {
		if !extBroken {
			st.EarliestDay = minDay(mustDay(st.EarliestDay), work.coverFrom).String()
		}
		if !forwardBroken {
			// Every signal day up to yesterday has now been asked for, so
			// the gaps between them are filled too.
			st.LastCompleteDay = maxDay(mustDay(st.LastCompleteDay), ceiling).String()
		}
	}
	if forwardBroken || extBroken {
		st.StopReason = "interrupted"
	} else {
		st.StopReason = ""
	}
	w.finishSeries(s, st, &out)
	return out
}

// garminActivityFeedPath is the activity feed endpoint.
const garminActivityFeedPath = "/activitylist-service/activities/search/activities"

// feedFloor asks Garmin for the account's oldest activity in one request. It
// is the activity feed's floor: there is nothing to walk below it, and unlike
// a wellness series the feed can answer the question directly.
func (w *garminWalker) feedFloor(ctx context.Context) (civilDay, error) {
	data, err := w.get(ctx, garminActivityFeedPath, map[string]string{
		"sortOrder": "asc", "start": "0", "limit": "1",
	})
	if err != nil {
		return civilDay{}, err
	}
	var items []json.RawMessage
	if err := json.Unmarshal(data, &items); err != nil || len(items) == 0 {
		return civilDay{}, nil
	}
	day, _ := dayFromValue(jsonStringField(items[0], garminActivityDayField))
	return day, nil
}

// pageFeed pages one date range of the activity feed, oldest first.
//
// The wire parameter for the offset is `start`, not `offset`: verified live
// 2026-09-07 by requesting start=5 and offset=5 against the same account —
// start=5 returned the sixth activity onward, offset=5 returned the same page
// as start=0, i.e. Garmin ignores `offset` entirely. The order parameter is
// `sortOrder=asc`, probed live 2026-09-13 on both reference homes, with and
// without a date range.
//
// The offset counts from zero WITHIN the range rather than from the rows
// already stored: once a fill can be bounded by dates, a stored-row count is
// not an offset into anything the server would return.
func (w *garminWalker) pageFeed(ctx context.Context, s garminSeries, from, to civilDay, forward bool, ceiling civilDay, st *store.GarminSeriesState, out *garminSeriesOutcome) (bool, error) {
	limit := w.opts.activityPageSize
	if limit < 1 {
		limit = 100
	}
	offset, pages := 0, 0
	for {
		if w.opts.maxPages > 0 && pages >= w.opts.maxPages {
			out.warned = true
			w.emit.warn(s.name, "max_pages_cap_hit",
				fmt.Sprintf("reached --max-pages cap of %d; the feed may be truncated. Re-run to continue.", w.opts.maxPages))
			return false, nil
		}
		params := map[string]string{
			"start":     strconv.Itoa(offset),
			"limit":     strconv.Itoa(limit),
			"sortOrder": "asc",
		}
		if !from.isZero() {
			params["startDate"] = from.String()
		}
		if !to.isZero() {
			params["endDate"] = to.String()
		}
		data, callErr := w.get(ctx, garminActivityFeedPath, params)
		if callErr != nil {
			if isWalkAborted(callErr) {
				return false, callErr
			}
			out.warned = true
			w.emit.warn(s.name, "page_fetch_failed", fmt.Sprintf("start=%d: %v", offset, callErr))
			return false, nil
		}
		var items []json.RawMessage
		if err := json.Unmarshal(data, &items); err != nil {
			out.warned = true
			w.emit.anomaly(s.name, "page_shape_unrecognized", 0, 0)
			return false, nil
		}
		pages++
		rows := make([]garminRow, 0, len(items))
		newest := civilDay{}
		for _, item := range items {
			id := activityIDOf(item)
			if id == "" {
				continue
			}
			day, _ := dayFromValue(jsonStringField(item, garminActivityDayField))
			newest = maxDay(newest, day)
			rows = append(rows, garminRow{id: id, day: day, data: item})
		}
		stored, storeErr := w.storeRows(s, rows)
		if storeErr != nil {
			return false, storeErr
		}
		out.stored += stored
		if forward {
			if !newest.isZero() {
				st.LastCompleteDay = maxDay(mustDay(st.LastCompleteDay), minDay(newest, ceiling)).String()
			}
			// Same rule as every other walk: a floor above the newest
			// complete day is not a range, so nothing is stamped from it.
			if !from.after(ceiling) {
				st.EarliestDay = minDay(mustDay(st.EarliestDay), from).String()
			}
			if saveErr := w.db.SaveGarminSeriesState(*st); saveErr != nil {
				return false, saveErr
			}
		}
		w.emit.progress(s.name, stored, fmt.Sprintf("start=%d", offset), st.LastCompleteDay)
		if len(items) < limit {
			return true, nil
		}
		offset += limit
	}
}

// walkActivities pages the activity feed oldest first, in the same two legs as
// every other series: an extension below the filled range when this run asks
// for one, then forward from the bookmark. The forward leg re-requests the
// bookmark day itself, which is free — rows upsert — and is what keeps an
// activity added late on that day from being missed.
func (w *garminWalker) walkActivities(ctx context.Context, s garminSeries) garminSeriesOutcome {
	out := garminSeriesOutcome{series: s.name}
	st, err := w.db.GetGarminSeriesState(s.name)
	if err != nil {
		out.errored, out.err = true, err
		return out
	}
	st = garminResumableState(st)
	now := today(w.opts.now, w.opts.loc)
	ceiling := completeDayCeiling(now)
	filled := garminSeriesFilled(st)
	w.noticeShallowSince(st)

	floor := civilDay{}
	switch w.opts.depth.mode {
	case depthFrom:
		floor = w.opts.depth.day
	case depthStored:
		if filled {
			floor = mustDay(st.EarliestDay)
		}
	}
	if floor.isZero() {
		probed, probeErr := w.feedFloor(ctx)
		if probeErr != nil {
			if isWalkAborted(probeErr) {
				out.errored, out.err = true, probeErr
				return out
			}
			out.warned = true
			w.emit.warn(s.name, "feed_floor_fetch_failed", probeErr.Error())
			return out
		}
		if probed.isZero() {
			// The feed answered, and this account has never recorded an
			// activity. There is nothing to page.
			w.finishSeries(s, st, &out)
			return out
		}
		floor = probed
	}

	// --- extension leg.
	if filled {
		earliest := mustDay(st.EarliestDay)
		if floor.before(earliest) {
			complete, fatal := w.pageFeed(ctx, s, floor, earliest.addDays(-1), false, ceiling, &st, &out)
			if fatal != nil {
				out.errored, out.err = true, fatal
				return out
			}
			if complete {
				st.EarliestDay = minDay(earliest, floor).String()
				if saveErr := w.db.SaveGarminSeriesState(st); saveErr != nil {
					out.errored, out.err = true, saveErr
					return out
				}
			}
		}
	}

	// --- forward leg.
	from := floor
	if filled {
		from = mustDay(st.LastCompleteDay)
	}
	complete, fatal := w.pageFeed(ctx, s, from, civilDay{}, true, ceiling, &st, &out)
	if fatal != nil {
		out.errored, out.err = true, fatal
		return out
	}
	if complete {
		st.LastCompleteDay = maxDay(mustDay(st.LastCompleteDay), ceiling).String()
		st.StopReason = "feed_exhausted"
	} else {
		st.StopReason = "interrupted"
	}
	w.finishSeries(s, st, &out)
	return out
}

func activityIDOf(item json.RawMessage) string {
	child, ok := jsonChild(item, "activityId")
	if !ok {
		return ""
	}
	var n json.Number
	if err := json.Unmarshal(child, &n); err == nil {
		return n.String()
	}
	var s string
	if err := json.Unmarshal(child, &s); err == nil {
		return s
	}
	return ""
}

// walkPerParent fetches one child document per parent id that is in range for
// this run and has no row in this series yet. The parent ids come from another
// series' stored rows, so a fan-out never enumerates anything the archive has
// not already seen, and MissingResourceIDs is what makes a re-run cost only the
// new parents.
//
// In range means the parent's own start day is on or after this run's floor —
// the same floor the parent feed walks from, resolved by the planner so the
// estimate and the walk cannot disagree (N131 decision D16). A deeper --since
// later extends a fan-out exactly like every other series: the bound is
// recomputed from the depth and the feed's saved range every run, and the
// id-set difference means only the parents that were out of range last time
// cost anything.
//
// Order: bound, then difference, then cap. --max-dependents stays what it has
// always been, a per-run safety valve over the work that remains.
//
// Each series supplies its own child URL and its own wrapper. The wrapper
// matters because several of these endpoints answer with a bare array, which
// carries no id of its own and which the store will not accept as a document
// at all; see the wrapping section above.
func (w *garminWalker) walkPerParent(ctx context.Context, s garminSeries) garminSeriesOutcome {
	out := garminSeriesOutcome{series: s.name}
	fan, err := w.planner.fanOutParents(s)
	if err != nil {
		out.errored, out.err = true, err
		return out
	}
	if fan.stored == 0 {
		w.emit.warn(s.name, "parent_table_empty",
			"no "+s.parentResource+" are stored yet, so there is nothing to fan out over; sync the "+s.parentResource+" series first")
		out.warned = true
		return out
	}
	if fan.unreadable > 0 {
		// Named once with its count rather than per parent, and never
		// fetched blind: a parent this run cannot place against its own
		// floor is outside the bound until the day it carries can be read.
		out.warned = true
		w.emit.warn(s.name, "parent_day_unreadable",
			fmt.Sprintf("%d stored %s carry no readable %s, so this run could not tell whether they start on or after %s; they were not fetched",
				fan.unreadable, s.parentResource, garminActivityDayField, fan.floor))
	}
	// A run whose floor leaves this fan-out nothing to ask for has asked a
	// complete question and got an empty answer; walkSeries' never-stored-a-row
	// warning names two causes, and neither of them is this one.
	out.boundedEmpty = !fan.floor.isZero() && len(fan.ids) == 0
	missing, err := w.db.MissingResourceIDs(s.resource, fan.ids)
	if err != nil {
		out.errored, out.err = true, err
		return out
	}
	outstanding := len(missing)
	capped := false
	if w.opts.maxDependents > 0 && len(missing) > w.opts.maxDependents {
		missing = missing[:w.opts.maxDependents]
		capped = true
	}
	st, err := w.db.GetGarminSeriesState(s.name)
	if err != nil {
		out.errored, out.err = true, err
		return out
	}
	for _, id := range missing {
		path, params := s.childReq(id)
		data, callErr := w.get(ctx, path, params)
		if callErr != nil {
			if isWalkAborted(callErr) {
				out.errored, out.err = true, callErr
				return out
			}
			out.warned = true
			w.emit.warn(s.name, "per_parent_fetch_failed", s.parentNoun+" "+id+": "+callErr.Error())
			continue
		}
		wrapped, wrapErr := s.wrapChild(id, data)
		if wrapErr != nil {
			out.warned = true
			var shape *perParentShapeError
			if !errors.As(wrapErr, &shape) {
				shape = &perParentShapeError{reason: "per_parent_wrap_failed", consumed: 1}
			}
			w.emit.anomaly(s.name, shape.reason, shape.consumed, shape.stored)
			continue
		}
		stored, storeErr := w.storeRows(s, []garminRow{{id: id, data: wrapped}})
		if storeErr != nil {
			out.errored, out.err = true, storeErr
			return out
		}
		out.stored += stored
		st.TotalRows += stored
		if saveErr := w.db.SaveGarminSeriesState(st); saveErr != nil {
			out.errored, out.err = true, saveErr
			return out
		}
	}
	if capped {
		out.warned = true
		w.emit.warn(s.name, "max_dependents_cap_hit",
			fmt.Sprintf("stopped after %d %s; re-run to continue, or raise --max-dependents", w.opts.maxDependents, s.parentResource))
	}
	w.emit.progress(s.name, out.stored, fmt.Sprintf("%d pending", outstanding-out.stored), "")
	w.mirrorSyncState(s.name, st)
	return out
}

// walkSingleDocument fetches one whole-account document and keeps exactly one
// row of it. There is no calendar walk and no id to fan out over: the request
// is the same every run and the row is replaced in place, so the archive
// always holds the current document rather than a pile of dated copies.
func (w *garminWalker) walkSingleDocument(ctx context.Context, s garminSeries) garminSeriesOutcome {
	out := garminSeriesOutcome{series: s.name}
	st, err := w.db.GetGarminSeriesState(s.name)
	if err != nil {
		out.errored, out.err = true, err
		return out
	}
	path, params := s.docReq()
	data, callErr := w.get(ctx, path, params)
	if callErr != nil {
		if isWalkAborted(callErr) {
			out.errored, out.err = true, callErr
			return out
		}
		out.warned = true
		w.emit.warn(s.name, "document_fetch_failed", callErr.Error())
		return out
	}
	wrapped, wrapErr := s.wrapDoc(data)
	if wrapErr != nil {
		out.warned = true
		var shape *perParentShapeError
		if !errors.As(wrapErr, &shape) {
			shape = &perParentShapeError{reason: "document_wrap_failed", consumed: 1}
		}
		w.emit.anomaly(s.name, shape.reason, shape.consumed, shape.stored)
		return out
	}
	stored, storeErr := w.storeRows(s, []garminRow{{id: s.docID, data: wrapped}})
	if storeErr != nil {
		out.errored, out.err = true, storeErr
		return out
	}
	out.stored += stored
	// Assigned, not accumulated. Every other series only ever stores rows it
	// did not have, so a running total is its row count; this one re-stores
	// the same id every run, and mirrorSyncState publishes this number to the
	// generated sync_state that doctor and tail read. Adding would make a
	// one-row table report one row per run ever made.
	st.TotalRows = stored
	if saveErr := w.db.SaveGarminSeriesState(st); saveErr != nil {
		out.errored, out.err = true, saveErr
		return out
	}
	w.emit.progress(s.name, out.stored, s.docID, "")
	w.mirrorSyncState(s.name, st)
	return out
}

func (w *garminWalker) walkSeries(ctx context.Context, s garminSeries) garminSeriesOutcome {
	var out garminSeriesOutcome
	switch s.kind {
	case seriesWindowed:
		out = w.walkWindowed(ctx, s)
	case seriesPerDay:
		out = w.walkPerDay(ctx, s)
	case seriesOffsetPaged:
		out = w.walkActivities(ctx, s)
	case seriesPerParent:
		out = w.walkPerParent(ctx, s)
	case seriesSingleDocument:
		out = w.walkSingleDocument(ctx, s)
	default:
		return garminSeriesOutcome{series: s.name, warned: true}
	}
	// A series that has still never stored a row after a completed run is
	// reporting a zero nobody has proven. Say so: the same silence covers
	// "this account has no such data" and "this tool asked wrong", and a
	// caller reading an empty table deserves to know which question is open.
	// A run whose own floor left the series nothing to ask for is neither.
	if !out.errored && !out.boundedEmpty {
		if st, err := w.db.GetGarminSeriesState(s.name); err == nil && st.TotalRows == 0 {
			out.warned = true
			w.emit.warn(s.name, "series_returned_no_rows",
				"this series has completed a run without ever storing a row; that is either an account with no such data or a request shape this tool has wrong, and an empty response cannot tell them apart")
		}
	}
	return out
}

// ---------------------------------------------------------------------------
// Kind names
// ---------------------------------------------------------------------------

func kindName(k garminSeriesKind) string {
	switch k {
	case seriesWindowed:
		return "windowed"
	case seriesPerDay:
		return "per_day"
	case seriesOffsetPaged:
		return "offset_paged"
	case seriesPerParent:
		return "per_parent"
	case seriesSingleDocument:
		return "single_document"
	}
	return "unknown"
}

// ---------------------------------------------------------------------------
// Command
// ---------------------------------------------------------------------------

// garminParseDepth turns --since into the three states the walk distinguishes.
func garminParseDepth(raw string) (garminDepth, error) {
	switch strings.TrimSpace(strings.ToLower(raw)) {
	case "":
		return garminDepth{mode: depthStored}, nil
	case "all":
		return garminDepth{mode: depthAll}, nil
	}
	day, err := parseCivilDay(strings.TrimSpace(raw))
	if err != nil {
		return garminDepth{}, fmt.Errorf("--since takes either `all` or a date in YYYY-MM-DD form; %q is neither", raw)
	}
	return garminDepth{mode: depthFrom, day: day}, nil
}

// garminSelectSeries resolves --series, defaulting to the whole catalog.
func garminSelectSeries(seriesFlag []string) ([]garminSeries, error) {
	if len(seriesFlag) == 0 {
		return garminSeriesCatalog(), nil
	}
	catalog := garminSeriesByName()
	var selected []garminSeries
	for _, raw := range seriesFlag {
		for _, name := range strings.Split(raw, ",") {
			name = strings.TrimSpace(name)
			if name == "" {
				continue
			}
			s, ok := catalog[name]
			if !ok {
				return nil, fmt.Errorf("unknown series %q; known series: %s", name, strings.Join(garminSeriesNames(), ", "))
			}
			selected = append(selected, s)
		}
	}
	if len(selected) == 0 {
		return nil, errors.New("no series selected")
	}
	return selected, nil
}

// garminPlanAll plans every selected series against the archive.
func garminPlanAll(planner *garminPlanner, selected []garminSeries) ([]garminSeriesPlan, error) {
	out := make([]garminSeriesPlan, 0, len(selected))
	for _, s := range selected {
		plan, err := planner.seriesPlan(s)
		if err != nil {
			return nil, err
		}
		out = append(out, plan)
	}
	return out, nil
}

// garminOutstandingCell renders a request count for --dry-run, whose column
// is what this run would cost. Only the feed's count is unknowable, and it is
// named rather than abbreviated to "variable", which is vocabulary from the
// implementation rather than from the question the caller asked.
func garminOutstandingCell(n int) string {
	if n < 0 {
		return "pages until the feed ends"
	}
	return strconv.Itoa(n)
}

// garminStatusOutstandingCell renders the same number for --status, where the
// column means outstanding WORK. A caught-up series still owes today's window
// and its refresh days every run, which is maintenance rather than debt, so a
// series complete through the newest complete day reads as up to date.
func garminStatusOutstandingCell(p garminSeriesPlan, ceiling civilDay) string {
	if p.Outstanding < 0 {
		return "pages until the feed ends"
	}
	// A single-document series is the account's current setting rather than a
	// dated observation: it is replaced in place every run, so its one
	// request is maintenance once the archive holds the document at all.
	if p.Kind == kindName(seriesSingleDocument) && p.Rows > 0 {
		return "up to date"
	}
	if p.Outstanding == 0 || p.LastComplete == ceiling.String() {
		return "up to date"
	}
	return strconv.Itoa(p.Outstanding)
}

func newGarminHistoryCmd(flags *rootFlags) *cobra.Command {
	var (
		seriesFlag             []string
		since                  string
		status                 bool
		delay                  time.Duration
		maxPages               int
		maxDependents          int
		pageSize               int
		strict                 bool
		dbPath                 string
		maxConsecutiveFailures int
	)

	cmd := &cobra.Command{
		Use:   "history",
		Short: "Build and maintain the local archive of your Garmin history",
		Long: `Build and maintain the local archive of Garmin's daily series.

Garmin serves daily statistics from date-range endpoints that accept at most
28 calendar days per request, and per-day endpoints that answer for exactly
one date, so this command owns the calendar walk: every series is walked from
its oldest day forward, and each keeps one bookmark saying how far it is
complete. Interrupting a run is safe — the next run continues from the
bookmark rather than starting again.

How far back to go is the one choice: --since all fetches everything the
account holds, --since YYYY-MM-DD starts there instead. With neither, a series
that already has history keeps the depth it has and only catches up to today.
That choice bounds every fetch the run makes, the per-activity detail, splits
and heart-rate zones included: those cover the activities that start on or
after the day the run starts from. A later, deeper --since extends the
archive downward without re-fetching what is already stored.

Before the expensive part of a run — the per-activity and per-day fetches —
the command prints what it is about to cost in requests, time and disk.
--dry-run prints that without making a single call, and --status reports what
each series already holds.`,
		// --status leads because the press's live matrix runs a command's
		// first example: a plain `history` on its empty sandbox home is a full
		// fill that outlasts any per-test timeout.
		Example: `  # What is already archived, and what each series still owes
  garmin-pp-cli history --status

  # Catch up every series since the last run
  garmin-pp-cli history

  # First fill: everything this account has
  garmin-pp-cli history --since all

  # Just this summer
  garmin-pp-cli history --since 2026-06-01

  # What a run would cost, without making a call
  garmin-pp-cli history --since all --dry-run`,
		RunE: func(cmd *cobra.Command, args []string) error {
			if len(args) > 0 {
				return usageErr(fmt.Errorf("history takes no positional arguments; use --since to choose how far back to fetch"))
			}
			depth, err := garminParseDepth(since)
			if err != nil {
				return usageErr(err)
			}
			if delay < 0 {
				return usageErr(fmt.Errorf("--delay cannot be negative"))
			}
			selected, err := garminSelectSeries(seriesFlag)
			if err != nil {
				return usageErr(err)
			}

			machine := wantsMachineOutput(flags)
			eventWriter := cmd.OutOrStdout()
			if machine {
				eventWriter = cmd.ErrOrStderr()
			}
			emit := &garminEmitter{w: eventWriter, machine: machine, noteW: cmd.ErrOrStderr()}

			if dbPath == "" {
				dbPath = garminArchivePath(cmd.Context(), cmd.ErrOrStderr())
			}
			db, err := store.OpenWithContext(cmd.Context(), dbPath)
			if err != nil {
				return fmt.Errorf("opening local database: %w", err)
			}
			defer db.Close()
			if err := db.EnsureGarminSeriesState(); err != nil {
				return err
			}

			now := time.Now
			planner := &garminPlanner{
				db: db, depth: depth, now: now, loc: time.Local,
				delay: delay, maxDependents: maxDependents,
			}

			// --status and --dry-run both answer from the archive alone.
			// Neither builds a client, so "no traffic" is a property of the
			// code path rather than a promise about it.
			if status {
				return garminPrintStatus(cmd, flags, planner, selected)
			}
			if flags.dryRun {
				return garminPrintDryRun(cmd, flags, planner, selected, delay)
			}

			c, err := flags.newClient()
			if err != nil {
				return err
			}
			c.NoCache = true

			walker := &garminWalker{
				client:  c,
				db:      db,
				emit:    emit,
				planner: planner,
				opts: garminWalkOptions{
					depth:                  depth,
					delay:                  delay,
					maxPages:               maxPages,
					maxDependents:          maxDependents,
					activityPageSize:       pageSize,
					strict:                 strict,
					maxConsecutiveFailures: maxConsecutiveFailures,
					now:                    now,
					loc:                    time.Local,
				},
				pacer: newGarminPacer(delay, nil),
			}

			started := time.Now()
			var total, success, warned, errored int
			var firstErr error
			estimated := false
			for _, s := range selected {
				// The estimate lands once, after the cheap series have
				// filled the archive this run reads its numbers from, and
				// before the first request that could take hours.
				if !estimated && garminIsExpensiveKind(s.kind) {
					estimated = true
					planner.signalLoaded = false
					if plans, planErr := garminPlanAll(planner, garminExpensiveSeries(selected)); planErr == nil {
						emit.estimate(garminEstimateOf(plans, depth, delay))
					}
				}
				emit.start(s.name)
				outcome := walker.walkSeries(cmd.Context(), s)
				total += outcome.stored
				switch {
				case outcome.errored:
					errored++
					if firstErr == nil {
						firstErr = fmt.Errorf("%s: %w", outcome.series, outcome.err)
					}
					emit.warn(s.name, "series_failed", outcome.err.Error())
				case outcome.warned:
					warned++
				default:
					success++
				}
				if outcome.errored && errors.Is(outcome.err, errGarminRateLimited) {
					emit.warn(s.name, "rate_limited_fail_fast",
						"Garmin rate-limited this account; the remaining series were not attempted. Wait before re-running.")
					emit.summary(total, len(selected), success, warned, errored, time.Since(started))
					return rateLimitErr(firstErr)
				}
				if outcome.errored && errors.Is(outcome.err, errGarminWallOfFailures) {
					emit.warn(s.name, "consecutive_failures_abort",
						fmt.Sprintf("%d requests failed in a row, so the remaining series were not attempted. A whole run failing usually means the credential stopped being accepted or the service is refusing this client, not that these particular requests were unlucky. Run `garmin-pp-cli auth status`, then re-run.", maxConsecutiveFailures))
					emit.summary(total, len(selected), success, warned, errored, time.Since(started))
					return apiErr(firstErr)
				}
			}
			elapsed := time.Since(started)
			emit.summary(total, len(selected), success, warned, errored, elapsed)

			if errored > 0 && strict {
				return apiErr(firstErr)
			}
			// The closing document, which is what a machine caller reads:
			// the same six keys the generated sync prints (sync.go
			// printJSONFiltered call), through the same helper, so --select
			// and --compact act on it the way they act there. It lands after
			// the exit-code checks for the same reason it does in sync.go — a
			// run that returns an error prints no summary document, so a
			// caller never reads one from a walk that did not finish.
			if machine {
				if err := printJSONFiltered(cmd.OutOrStdout(), map[string]any{
					"total_records": total,
					"resources":     len(selected),
					"success":       success,
					"warned":        warned,
					"errored":       errored,
					"duration_ms":   elapsed.Milliseconds(),
				}, flags); err != nil {
					return err
				}
			}
			return nil
		},
	}

	cmd.Flags().StringVar(&since, "since", "",
		"How far back to fetch: the word all for everything this account holds, or a date (YYYY-MM-DD). "+
			"Without it, a series that already has history keeps its depth and only catches up to today.")
	cmd.Flags().BoolVar(&status, "status", false,
		"Report what each series already holds and what it still owes, without making a request.")

	// Mechanism flags. They stay functional — an escape hatch is worth
	// having when a run meets something nobody predicted — but they are
	// hidden, because every one of them is an implementation detail leaking
	// into a choice the caller should not have to make (N131 decision D12).
	cmd.Flags().StringSliceVar(&seriesFlag, "series", nil,
		"Series to walk (comma-separated). Default: every series. Known: "+strings.Join(garminSeriesNames(), ", "))
	cmd.Flags().DurationVar(&delay, "delay", 300*time.Millisecond,
		"Pause between API calls. The default paced a 94-window live fill without a single 429.")
	cmd.Flags().IntVar(&maxPages, "max-pages", 0,
		"Cap on activity-feed pages per leg (0 = until the feed ends).")
	cmd.Flags().IntVar(&maxDependents, "max-dependents", 0,
		"Cap on per-activity fetches per fan-out series — heart-rate zones, detail, splits — in one run (0 = no cap).")
	cmd.Flags().IntVar(&pageSize, "page-size", 100, "Activity-feed page size.")
	cmd.Flags().BoolVar(&strict, "strict", false, "Exit non-zero when any series fails. By default a failed series warns and the run continues.")
	cmd.Flags().IntVar(&maxConsecutiveFailures, "max-consecutive-failures", defaultMaxConsecutiveFailures,
		"End the run when this many requests fail in a row. A whole run failing usually means the credential stopped being accepted or the service is refusing this client, not that these requests were unlucky.")
	cmd.Flags().StringVar(&dbPath, "db", "", "SQLite database file path. The default is this home's data directory data.db, which is named for the home rather than for the credential in use, so a token refresh never orphans it; pass --db to read or write a different file.")
	// --strict is NOT in this list (N131 decision D21). "Exit non-zero when a
	// series fails" is a choice about how a caller wants the run to end, not an
	// implementation detail: a scripted or scheduled fill needs it, and a
	// hidden flag is one a caller cannot discover. Everything still hidden is
	// a knob whose right value this command already knows.
	for _, hidden := range []string{"series", "delay", "max-pages", "max-dependents", "page-size", "max-consecutive-failures", "db"} {
		if err := cmd.Flags().MarkHidden(hidden); err != nil {
			panic("history: " + err.Error())
		}
	}

	return cmd
}

// garminIsExpensiveKind marks the series shapes whose cost is worth warning
// about before they start: one request per activity, and one per day.
func garminIsExpensiveKind(k garminSeriesKind) bool {
	return k == seriesPerParent || k == seriesPerDay
}

func garminExpensiveSeries(selected []garminSeries) []garminSeries {
	var out []garminSeries
	for _, s := range selected {
		if garminIsExpensiveKind(s.kind) {
			out = append(out, s)
		}
	}
	return out
}

// garminPrintStatus reports each series' filled range and outstanding work.
func garminPrintStatus(cmd *cobra.Command, flags *rootFlags, planner *garminPlanner, selected []garminSeries) error {
	plans, err := garminPlanAll(planner, selected)
	if err != nil {
		return err
	}
	if flags.asJSON {
		return flags.printJSON(cmd, map[string]any{"series": plans})
	}
	rows := make([][]string, 0, len(plans))
	for _, p := range plans {
		rows = append(rows, []string{
			p.Series, strconv.Itoa(p.Rows), p.Earliest, p.LastComplete,
			garminStatusOutstandingCell(p, planner.ceiling()), p.StopReason,
		})
	}
	return flags.printTable(cmd,
		[]string{"SERIES", "ROWS", "FILLED FROM", "COMPLETE THROUGH", "OUTSTANDING", "STOPPED BECAUSE"}, rows)
}

// garminPrintDryRun reports what a run would cost without making one request.
func garminPrintDryRun(cmd *cobra.Command, flags *rootFlags, planner *garminPlanner, selected []garminSeries, delay time.Duration) error {
	plans, err := garminPlanAll(planner, selected)
	if err != nil {
		return err
	}
	est := garminEstimateOf(plans, planner.depth, delay)
	if flags.asJSON {
		return flags.printJSON(cmd, map[string]any{
			"plan":     plans,
			"estimate": est,
			"delay_ms": delay.Milliseconds(),
		})
	}
	rows := make([][]string, 0, len(plans))
	for _, p := range plans {
		rows = append(rows, []string{p.Series, p.Kind, garminOutstandingCell(p.Outstanding), p.Since, p.Note})
	}
	if err := flags.printTable(cmd, []string{"SERIES", "KIND", "REQUESTS", "SINCE", "NOTE"}, rows); err != nil {
		return err
	}
	fmt.Fprintln(cmd.ErrOrStderr(), est.line())
	return nil
}

// ---------------------------------------------------------------------------
// Archive path
// ---------------------------------------------------------------------------

// garminArchiveName is the one archive file name this tool's design names:
// N131 §3, "SQLite archive at <data>/data.db".
const garminArchiveName = "data.db"

// garminScopedArchivePattern matches the token-scoped archive name the
// generated resolver invents, `data-<sha256(auth header)[:12]>.db`.
var garminScopedArchivePattern = regexp.MustCompile(
	`^data-[0-9a-f]{` + strconv.Itoa(defaultDBScopeHashLen) + `}\.db$`)

// garminArchivePath resolves the archive the novel commands read and write,
// and it is deliberately not the generated resolver.
//
// The generated defaultDBPathInDir names the archive after a hash of the
// current Authorization header, so a home's archive is scoped to the
// credential in use. Garmin's DI chain rotates its refresh token on every
// refresh and its access token roughly daily, so that name changes under a
// daily sync and every rotation orphans the previous file: rows already walked
// stop being visible and the next `history` re-walks years of history into a
// new file. Nothing about a Garmin home needs that scoping — the design binds
// one account to one home (N131 §2 Q3), so the home already is the isolation
// boundary and the archive can carry the plain name §3 gives it.
//
// The fix has to survive the generated commands too, because `sync`,
// `analytics` and `search` resolve through defaultDBPath and must not end up
// on a different file from `history` and `insights`. That is why this resolver
// does not merely return a different path: it makes the unscoped file exist.
// The generated resolver prefers a scoped file when one is present and falls
// through to an existing unscoped file otherwise, so once the scoped file is
// gone and data.db is there, every generated command follows.
//
// dir comes from the generated resolver's own answer rather than from a second
// call to cliutil.DataDir, so the pin lands in exactly the directory the
// generated resolver reads, including on its fallback branches.
func garminArchivePath(ctx context.Context, warn io.Writer) string {
	generated := defaultDBPath("garmin-pp-cli")
	dir := filepath.Dir(generated)
	unscoped := filepath.Join(dir, garminArchiveName)

	scoped := garminScopedArchives(dir)

	if _, err := os.Stat(unscoped); err == nil {
		if len(scoped) > 0 {
			fmt.Fprintf(warn,
				"warning: %s holds both %s and %d token-scoped archive(s) (%s).\n"+
					"  history and insights use %s. The generated sync, analytics and search prefer the\n"+
					"  scoped file, so they are writing a different archive: move or delete the scoped\n"+
					"  file(s), or pass --db to pin one file explicitly.\n",
				dir, garminArchiveName, len(scoped), strings.Join(scoped, ", "), garminArchiveName)
		}
		return unscoped
	} else if !os.IsNotExist(err) {
		// The directory is unreadable or something stranger; guessing here
		// would be worse than deferring to the generated answer.
		return generated
	}

	switch len(scoped) {
	case 0:
		if err := garminPinArchive(unscoped); err != nil {
			fmt.Fprintf(warn, "warning: could not create %s (%v); using %s\n", unscoped, err, generated)
			return generated
		}
	case 1:
		if err := garminMigrateScopedArchive(ctx, filepath.Join(dir, scoped[0]), unscoped); err != nil {
			fmt.Fprintf(warn, "warning: could not rename %s to %s (%v); using it where it is\n",
				scoped[0], garminArchiveName, err)
			return filepath.Join(dir, scoped[0])
		}
		fmt.Fprintf(warn,
			"notice: renamed the token-scoped archive %s to %s in %s.\n"+
				"  The archive is now named for this home, not for the credential, so a token refresh\n"+
				"  no longer orphans it.\n",
			scoped[0], garminArchiveName, dir)
	default:
		// Two or more scoped files means two credentials have already written
		// separate archives here. Picking one would silently discard the
		// other, so this starts a clean unscoped archive and names them all.
		if err := garminPinArchive(unscoped); err != nil {
			fmt.Fprintf(warn, "warning: could not create %s (%v); using %s\n", unscoped, err, generated)
			return generated
		}
		fmt.Fprintf(warn,
			"warning: %s holds %d token-scoped archives (%s) and no %s, so none of them could be\n"+
				"  renamed without discarding the others. Started an empty %s; pass --db to read one of\n"+
				"  the existing files instead.\n",
			dir, len(scoped), strings.Join(scoped, ", "), garminArchiveName, garminArchiveName)
	}
	return unscoped
}

// garminScopedArchives lists the token-scoped archive names in dir, sorted.
func garminScopedArchives(dir string) []string {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil
	}
	var found []string
	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		if garminScopedArchivePattern.MatchString(e.Name()) {
			found = append(found, e.Name())
		}
	}
	sort.Strings(found)
	return found
}

// garminPinArchive creates an empty archive file so the generated resolver's
// "an unscoped archive exists" branch takes over for the generated commands
// too. A zero-byte file is a valid empty SQLite database, so the first open
// migrates it normally. Permissions match what the store enforces afterwards.
func garminPinArchive(path string) error {
	if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
		return err
	}
	f, err := os.OpenFile(path, os.O_CREATE|os.O_EXCL|os.O_WRONLY, 0o600) // #nosec G304 -- app-derived archive path: garminArchivePath's own <data-dir>/data.db (--db never reaches here).
	if err != nil {
		return err
	}
	return f.Close()
}

// garminMigrateScopedArchive renames a token-scoped archive to the unscoped
// name so its rows are not orphaned.
//
// Deviation from "one atomic rename": the store opens in WAL mode, so a
// -wal/-shm pair can sit beside the archive, and renaming the main file alone
// would strand the committed transactions in the stale WAL. Opening and
// closing the store first checkpoints the WAL back into the main file, after
// which the single rename carries everything. Any sidecar SQLite still leaves
// behind is renamed alongside rather than deleted.
func garminMigrateScopedArchive(ctx context.Context, scoped, unscoped string) error {
	if _, err := os.Stat(scoped + "-wal"); err == nil {
		if db, openErr := store.OpenWithContext(ctx, scoped); openErr == nil {
			_ = db.Close()
		}
	}
	if err := os.Rename(scoped, unscoped); err != nil {
		return err
	}
	for _, suffix := range []string{"-wal", "-shm"} {
		if _, err := os.Stat(scoped + suffix); err == nil {
			_ = os.Rename(scoped+suffix, unscoped+suffix)
		}
	}
	return nil
}
